head.script:
// modal: 팝업 modal 여부, frameModal: modal 영역(frameId·"top")
scwin.openPopup = function (modal, frameModal) {
	$p.openPopup("/sample/common_link/wframe_Modal_modaless_WESD-496_(WSQ-4614)_popup.xml", {
		id: "wframePop",
		type: "wframePopup",
		popupName: "직원 조회",
		width: 560,
		height: 300,
		top: "167px",
		left: "187px",
		modal: modal,
		useModalStack: true,
		resizable: true,
		scrollbars: true,
		frameModal: frameModal
	});
};
scwin.btn_wframeModless_onclick = function (e) {
	scwin.openPopup(false, $p.getFrameId());
};
scwin.btn_wframePopup_onclick = function (e) {
	scwin.openPopup(true, $p.getFrameId());
};
scwin.btn_wframeTop_onclick = function (e) {
	scwin.openPopup(true, "top");
};
